(()=>{'use strict';
const STORE='sales_forecast_v16',CLOSE_KEY='sales_forecast_vendor_closed_v66',RAW_API='https://raw.githubusercontent.com/yhbae106/Sales_Forecast/main/shared-data/sales-history.json',CONTENTS_API='https://api.github.com/repos/yhbae106/Sales_Forecast/contents/shared-data/sales-history.json',EXPECT_KEY='sales_forecast_expected_shared_v98';
const $=s=>document.querySelector(s),status=m=>{const e=$('#status');if(e)e.textContent=m};
const setBrand=()=>{const e=$('.eyebrow'),h=$('.top h1');if(e)e.textContent='SCM SALES Forecast CONTROL TOWER';if(h)h.textContent='종합도매 매출 · MBO 운영 대시보드';document.title='SCM SALES Forecast CONTROL TOWER | 종합도매 매출 · MBO 운영 대시보드'};
const short=d=>d?`${Number(d.slice(5,7))}/${Number(d.slice(8))}까지 반영 완료`:'공용 데이터 대기';
const asofText=d=>d?`${Number(d.slice(5,7))}/${Number(d.slice(8))} 기준`:'데이터 확인 중';
const load=src=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.async=false;s.onload=resolve;s.onerror=()=>reject(new Error(src+' 로드 실패'));document.body.appendChild(s)});
const waitSeed=(max=4500)=>new Promise(resolve=>{if(window.SEED_DATA?.dailyRecords?.length)return resolve(true);const started=Date.now(),id=setInterval(()=>{if(window.SEED_DATA?.dailyRecords?.length||Date.now()-started>=max){clearInterval(id);resolve(!!window.SEED_DATA?.dailyRecords?.length)}},40)});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function monthTotal(shared,month){return(shared?.uploads||[]).filter(r=>String(r.d||r.date||'').slice(0,7)===month).reduce((s,r)=>s+Number(r.a??r.amount??0),0)}
function expectedShared(){try{return JSON.parse(sessionStorage.getItem(EXPECT_KEY)||'null')}catch(e){return null}}
function matchesExpected(shared,expected){if(!expected)return true;const last=lastDate(shared);if(expected.updatedAt&&shared?.updatedAt&&String(shared.updatedAt)>String(expected.updatedAt))return !expected.last||last>=expected.last;if(expected.updatedAt&&shared?.updatedAt!==expected.updatedAt)return false;if(expected.last&&last!==expected.last)return false;if(expected.month&&Number.isFinite(Number(expected.total))&&Math.abs(monthTotal(shared,expected.month)-Number(expected.total))>.5)return false;return true}
function validateShared(shared){const src=[...(shared?.sourceFiles||[])].filter(x=>x&&(x.month||x.date)).sort((a,b)=>String(a.lastDate||a.date||'').localeCompare(String(b.lastDate||b.date||''))).at(-1);if(!src?.month||!Number.isFinite(Number(src.total)))return shared;const got=monthTotal(shared,src.month);if(Math.abs(got-Number(src.total))>.5)throw new Error('공용 데이터 무결성 오류: '+src.month+' 누계 불일치');return shared}
async function readRawShared(){const r=await fetch(RAW_API+'?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error('공용 데이터 HTTP '+r.status);return r.json()}
async function readContentsShared(){const r=await fetch(CONTENTS_API+'?ref=main&t='+Date.now(),{headers:{Accept:'application/vnd.github.raw+json','X-GitHub-Api-Version':'2022-11-28'},cache:'no-store'});if(!r.ok)throw new Error('GitHub 최신 데이터 HTTP '+r.status);return r.json()}
async function readSharedApi(){const expected=expectedShared();let shared=validateShared(await readRawShared());if(!expected||matchesExpected(shared,expected)){if(expected)sessionStorage.removeItem(EXPECT_KEY);return shared}for(let i=0;i<4;i++){try{const fresh=validateShared(await readContentsShared());shared=fresh;if(matchesExpected(fresh,expected)){sessionStorage.removeItem(EXPECT_KEY);return fresh}}catch(e){}await sleep(250+i*250);try{const raw=validateShared(await readRawShared());shared=raw;if(matchesExpected(raw,expected)){sessionStorage.removeItem(EXPECT_KEY);return raw}}catch(e){}}throw new Error('최신 공용 데이터 동기화 대기 · 잠시 후 자동 재조회해 주세요.')}
function lastDate(shared){const a=(shared.sourceFiles||[]).map(x=>x.lastDate||x.date).filter(Boolean),b=(shared.uploads||[]).map(x=>x.d||x.date).filter(Boolean);return [...a,...b].sort().at(-1)||''}
function koreaDate(iso){if(!iso)return'';try{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(iso));const o=Object.fromEntries(parts.map(p=>[p.type,p.value]));return`${o.year}-${o.month}-${o.day}`}catch(e){return''}}
function displayDate(shared,dataLast){const updated=koreaDate(shared?.updatedAt);return[updated,dataLast].filter(Boolean).sort().at(-1)||dataLast||''}
function applyDisplayDate(){const d=window.__SF_DISPLAY_DATE||window.__SF_SHARED_LAST||'';if(d){status(short(d));const a=$('#asof');if(a)a.textContent=asofText(d)}}
async function hydrate(){const shared=await readSharedApi();const up=Array.isArray(shared.uploads)?shared.uploads:[];window.__SF_SHARED_UPLOADS=up;window.__sfSharedMeta=shared;window.__SF_UI_TEXT=shared.uiText&&typeof shared.uiText==='object'?shared.uiText:{};window.__SF_DASHBOARD_THEME=['default','a','b','c','d'].includes(String(shared.dashboardTheme||'default').toLowerCase())?String(shared.dashboardTheme||'default').toLowerCase():'default';document.documentElement.dataset.sfTheme=window.__SF_DASHBOARD_THEME;window.__SF_LAST_UPLOAD_DIFF=shared.lastUploadDiff||null;window.__sfReadShared=window.__sfReadShared||readSharedApi;let local={};try{local=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem('sales_forecast_v15')||'{}')}catch(e){}let localClosed={};try{localClosed=JSON.parse(localStorage.getItem(CLOSE_KEY)||'{}')}catch(e){}const lean={mbo:shared.mbo&&Object.keys(shared.mbo).length?shared.mbo:(local.mbo||{}),gmbo:shared.gmbo&&Object.keys(shared.gmbo).length?shared.gmbo:(local.gmbo||local.groupMbo||{}),sched:shared.sched&&Object.keys(shared.sched).length?shared.sched:(local.sched||{}),up};const sharedClosed=shared.closedVendors&&typeof shared.closedVendors==='object'?shared.closedVendors:null;window.__SF_BOOTSTRAP_LEAN=lean;window.__SF_SHARED_CLOSED=sharedClosed||localClosed;try{localStorage.setItem(STORE,JSON.stringify(lean));localStorage.setItem(CLOSE_KEY,JSON.stringify(window.__SF_SHARED_CLOSED));window.__SF_SHARED_STORAGE_FAILED=false}catch(e){window.__SF_SHARED_STORAGE_FAILED=true}const last=lastDate(shared);window.__SF_SHARED_LAST=last;window.__SF_DISPLAY_DATE=displayDate(shared,last);applyDisplayDate();return last}
function installMemoryStore(){if(!window.__SF_SHARED_STORAGE_FAILED)return()=>{};const orig=Storage.prototype.getItem;Storage.prototype.getItem=function(k){if(this===localStorage&&(k===STORE||k==='sales_forecast_v15'))return JSON.stringify(window.__SF_BOOTSTRAP_LEAN||{});if(this===localStorage&&k===CLOSE_KEY)return JSON.stringify(window.__SF_SHARED_CLOSED||{});return orig.call(this,k)};return()=>{Storage.prototype.getItem=orig}}
(async()=>{setBrand();try{await hydrate()}catch(e){status('공용 데이터 연결 오류: '+e.message)}const restoreStore=installMemoryStore();await load('v16-legacy.js?v=103');await waitSeed();restoreStore();await load('shared-v31.js?v=103');await load('master-upload-v34.js?v=103');await load('upload-diff-v99.js?v=103');await load('kpi-layout-v37.js?v=103');await load('upper-history-v39.js?v=103');await load('vendor-mbo-gap-v43.js?v=103');await load('vendor-close-ui-v67.js?v=103');await load('forecast-progress-v81.js?v=103');await load('group-info-no-mbo-v82.js?v=103');setBrand();applyDisplayDate();setTimeout(applyDisplayDate,100);setTimeout(applyDisplayDate,800);window.__sfCoreReady=true;window.dispatchEvent(new Event('sf-core-ready'));await load('group-no-mbo-final-v87.js?v=103')})().catch(e=>status('대시보드 로딩 오류: '+e.message));
})();